package com.cinenest.iot.internal;
import java.time.Instant;import java.util.UUID;import java.lang.reflect.Proxy;
/** Test-only clock/fixture adapter; production always reads PostgreSQL time. */
public final class IotFaults {
 public static Object clock(Object bean,Instant instant)throws Exception{Object target=org.springframework.test.util.AopTestUtils.getUltimateTargetObject(bean);Object original=org.springframework.test.util.ReflectionTestUtils.getField(target,"repo");IotRepository proxy=(IotRepository)Proxy.newProxyInstance(IotRepository.class.getClassLoader(),new Class<?>[]{IotRepository.class},(p,m,a)->{if(m.getName().equals("now"))return instant;try{m.setAccessible(true);return m.invoke(original,a);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});org.springframework.test.util.ReflectionTestUtils.setField(target,"repo",proxy);return original;}
 public static void restore(Object bean,Object repo)throws Exception{org.springframework.test.util.ReflectionTestUtils.setField((Object)org.springframework.test.util.AopTestUtils.getUltimateTargetObject(bean),"repo",repo);}
 public static void register(org.springframework.context.ApplicationContext context,UUID id,UUID venue,UUID room){var e=new org.springframework.mock.env.MockEnvironment().withProperty("cinenest.iot.fixture-device",id.toString()).withProperty("cinenest.iot.fixture-venue",venue.toString()).withProperty("cinenest.iot.fixture-room",room.toString()).withProperty("cinenest.iot.fixture-enabled","true").withProperty("cinenest.iot.fixture-online","true");new IotBootstrap(context.getBean(IotRepository.class),context.getBean(IotPolicy.class),e,context.getBean(com.cinenest.rooms.PackageConstraints.class)).run(new org.springframework.boot.DefaultApplicationArguments());}
}
